"""OpenAI Batch API helper module for LangExtract.

This module provides batch inference support using the OpenAI Batch API. It
handles:
- JSONL input file upload and batch job submission
- Job polling with timeout enforcement
- Result download, per-item error handling and order preservation

The OpenAI Batch API processes requests asynchronously (up to 24h) at reduced
cost. Requests are uploaded as a JSONL file where each line carries a
``custom_id`` used to reassemble the responses in the original prompt order.
"""

from __future__ import annotations

import collections.abc
import dataclasses
import io
import json
import time
from typing import Any, Callable, Sequence

from absl import logging

from langextract.core import exceptions

_CUSTOM_ID_PREFIX = 'idx-'
_ENDPOINT = '/v1/chat/completions'
_COMPLETION_WINDOW = '24h'

# Terminal batch job states as reported by the OpenAI Batch API.
_TERMINAL_OK = frozenset({'completed'})
_TERMINAL_FAIL = frozenset({'failed', 'expired', 'cancelled'})

# Number of times an output file download is attempted before giving up when
# the API returns a 403 (missing Files Read permission).
_DOWNLOAD_ATTEMPTS = 3


@dataclasses.dataclass
class BatchConfig:
  """Configuration for OpenAI Batch API processing.

  Attributes:
    enabled: Whether batch mode is active.
    threshold: Minimum number of prompts required to trigger batch processing.
    completion_window: Batch completion window. Only '24h' is supported.
    poll_interval: Seconds to wait between job status checks.
    timeout: Maximum seconds to wait for a job to complete. Defaults to more
      than 24 hours because that is the maximum completion window.
    max_requests_per_job: Maximum number of requests submitted in a single
      batch job. Larger request sets are split across multiple jobs.
    metadata: Optional metadata forwarded to the batch create call.
    on_job_create: Optional callback invoked with each created job object.
  """

  enabled: bool = False
  threshold: int = 1
  completion_window: str = _COMPLETION_WINDOW
  poll_interval: int | float = 30
  timeout: int | float = 172800  # 48h, greater than the 24h completion window.
  max_requests_per_job: int = 50000
  metadata: dict | None = None
  on_job_create: Callable[[Any], None] | None = None

  def __post_init__(self) -> None:
    """Validate the completion window on construction."""
    if self.completion_window != _COMPLETION_WINDOW:
      raise ValueError(
          "Unsupported completion_window "
          f"{self.completion_window!r}; only '24h' is supported."
      )

  @classmethod
  def from_dict(cls, obj: Any) -> BatchConfig:
    """Coerce ``obj`` into a :class:`BatchConfig`.

    Args:
      obj: A ``BatchConfig`` (returned unchanged), ``True`` / ``False`` (mapped
        to an enabled / disabled config), or a mapping of field values.

    Returns:
      A ``BatchConfig`` instance.

    Raises:
      TypeError: If ``obj`` is not a BatchConfig, bool, or mapping.
    """
    if isinstance(obj, cls):
      return obj
    if obj is True:
      return cls(enabled=True)
    if obj is False:
      return cls(enabled=False)
    if isinstance(obj, collections.abc.Mapping):
      valid_keys = {f.name for f in dataclasses.fields(cls)}
      filtered = {k: v for k, v in obj.items() if k in valid_keys}
      return cls(**filtered)
    raise TypeError('batch must be a mapping')


def _get(obj: Any, key: str, default: Any = None) -> Any:
  """Read ``key`` from ``obj`` supporting both mappings and objects."""
  if isinstance(obj, collections.abc.Mapping):
    return obj.get(key, default)
  return getattr(obj, key, default)


def _errors_text(errors: Any) -> str:
  """Render a batch job ``errors`` field to a human-readable string."""
  if errors is None:
    return ''
  data = _get(errors, 'data', None)
  messages = []
  if data:
    for item in data:
      message = _get(item, 'message', None)
      if message:
        messages.append(str(message))
  if messages:
    return '; '.join(messages)
  return str(errors)


def _error_message(error: Any) -> str:
  """Render a single error object to a human-readable string."""
  if error is None:
    return ''
  message = _get(error, 'message', None)
  if message:
    return str(message)
  return str(error)


def _is_permission_error(exc: BaseException) -> bool:
  """Return True if ``exc`` looks like an HTTP 403 permission error."""
  for attr in ('status_code', 'status', 'code'):
    value = getattr(exc, attr, None)
    if value == 403 or value == '403':
      return True
  return '403' in str(exc)


def _read_content(resp: Any) -> str:
  """Extract the text body from a files.content() response."""
  if resp is None:
    return ''
  if isinstance(resp, str):
    return resp
  if isinstance(resp, bytes):
    return resp.decode('utf-8')

  text = getattr(resp, 'text', None)
  if isinstance(text, str):
    return text
  if isinstance(text, bytes):
    return text.decode('utf-8')

  content = getattr(resp, 'content', None)
  if isinstance(content, str):
    return content
  if isinstance(content, bytes):
    return content.decode('utf-8')

  read = getattr(resp, 'read', None)
  if callable(read):
    data = read()
    if isinstance(data, bytes):
      return data.decode('utf-8')
    if isinstance(data, str):
      return data

  return str(resp)


def _download_file(client: Any, file_id: str, cfg: BatchConfig) -> str:
  """Download a batch output/error file, retrying on 403 errors.

  Args:
    client: The OpenAI client instance.
    file_id: Identifier of the file to download.
    cfg: Batch configuration providing the poll interval used between retries.

  Returns:
    The file contents as a string.

  Raises:
    InferenceRuntimeError: If the download keeps failing with a 403 after
      ``_DOWNLOAD_ATTEMPTS`` attempts, or on any other download failure.
  """
  for attempt in range(_DOWNLOAD_ATTEMPTS):
    try:
      return _read_content(client.files.content(file_id))
    except exceptions.InferenceError:
      raise
    except Exception as e:  # pylint: disable=broad-except
      if _is_permission_error(e):
        if attempt < _DOWNLOAD_ATTEMPTS - 1:
          time.sleep(cfg.poll_interval)
          continue
        raise exceptions.InferenceRuntimeError(
            'Files Read permission denied while downloading batch output '
            f'file {file_id} (HTTP 403).',
            original=e,
        ) from e
      raise exceptions.InferenceRuntimeError(
          f'Failed to download batch file {file_id}: {e}', original=e
      ) from e
  # Unreachable, but keeps static analyzers satisfied.
  return ''


